<form id="admin-record-form" class="cbn-flex-form portal-resource-form" data-form="true" data-resource="organizations"><div class="portal-resource-field" data-editor-field="name"><label for="editor-organizations-name">نام<span class="portal-field-requirement">الزامی</span></label><input id="editor-organizations-name" data-field="name" type="text" required="" maxLength="255" name="name"/></div><div class="portal-resource-field" data-editor-field="email"><label for="editor-organizations-email">ایمیل<span class="portal-field-requirement">اختیاری</span></label><input id="editor-organizations-email" data-field="email" type="email" maxLength="255" dir="ltr" name="email"/></div><div class="portal-resource-field" data-editor-field="phone"><label for="editor-organizations-phone">تلفن<span class="portal-field-requirement">اختیاری</span></label><input id="editor-organizations-phone" data-field="phone" type="text" maxLength="40" dir="ltr" name="phone"/></div><div class="portal-resource-field" data-editor-field="fax"><label for="editor-organizations-fax">فکس<span class="portal-field-requirement">اختیاری</span></label><input id="editor-organizations-fax" data-field="fax" type="text" maxLength="40" name="fax"/></div><div class="portal-resource-field" data-editor-field="sms_number"><label for="editor-organizations-sms_number">شمارهٔ پیامک<span class="portal-field-requirement">اختیاری</span></label><input id="editor-organizations-sms_number" data-field="sms_number" type="text" maxLength="40" name="sms_number"/></div><div class="portal-resource-field" data-editor-field="address"><label for="editor-organizations-address">نشانی<span class="portal-field-requirement">اختیاری</span></label><input id="editor-organizations-address" data-field="address" type="text" maxLength="100000" name="address"/></div></form>